1	--!
2	--! @author:    N. Selvarajah
3	--! @brief:     Unit tests for the SPI TX module.
4	--!
5	--! @license    This project is released under the terms of the MIT License. See LICENSE for more details.
6	--!
7	
8	-- vunit: run_all_in_same_sim
9	
10	library ieee;
11	use ieee.std_logic_1164.all;
12	use ieee.numeric_std.all;
13	use ieee.math_real.all;
14	
15	library vunit_lib;
16	context vunit_lib.vunit_context;
17	
18	library osvvm;
19	use osvvm.RandomPkg.RandomPType;
20	
21	use work.tb_utils.all;
22	use work.utils_pkg.all;
23	
24	
25	entity tb_spi_tx is
26	    generic (
27	        runner_cfg: string := runner_cfg_default;
28	        tb_path: string
29	    );
30	end entity;
31	
32	architecture tb of tb_spi_tx is
33	    -------------------------------------------------------------
34	    -- Internal tb signals/constants
35	    -------------------------------------------------------------
36	    constant PROPAGATION_TIME: time := 1 ns;
37	    constant SIMULATION_TIMEOUT_TIME: time := 1 ms;
38	    constant ENABLE_DEBUG_PRINT: boolean := false;
39	
40	    constant SYS_CLK_FREQUENCY: real := real(50e6);
41	    constant SYS_CLK_PHASE: time := 0 fs;
42	
43	    signal spi_clk_enable: std_ulogic := '1';
44	    signal simulation_done: boolean := false;
45	    -------------------------------------------------------------
46	
47	    -------------------------------------------------------------
48	    -- DuT signals, constants
49	    -------------------------------------------------------------
50	    constant SPI_CLK_POLARITY: bit := '0';
51	    constant SPI_CLK_PHASE: bit := '0';
52	    constant CONTROLLER_AND_NOT_PERIPHERAL: boolean := true;
53	    constant MSB_FIRST_AND_NOT_LSB: boolean := true;
54	    constant DATA_WIDTH: positive := 8;
55	
56	    package spi_pkg_constrained is new work.spi_pkg
57	        generic map (
58	            DATA_WIDTH => DATA_WIDTH,
59	            MSB_FIRST_AND_NOT_LSB => MSB_FIRST_AND_NOT_LSB
60	        );
61	    use spi_pkg_constrained.all;
62	
63	    signal spi_clk: std_ulogic := '0';
64	    signal rst_n: std_ulogic := '1';
65	
66	    signal tx_data: std_ulogic_vector(DATA_WIDTH - 1 downto 0) := (others => '0');
67	    signal tx_data_valid: std_ulogic := '0';
68	    signal tx_data_ack: std_ulogic;
69	
70	    signal spi_clk_out: std_ulogic;
71	    signal serial_data_out: std_logic;
72	    signal spi_chip_select_n: std_ulogic;
73	
74	    signal tx_is_ongoing: std_ulogic;
75	    -------------------------------------------------------------
76	begin
77	    ------------------------------------------------------------
78	    -- CLOCK Generation
79	    ------------------------------------------------------------
80	    generate_advanced_clock(spi_clk, SYS_CLK_FREQUENCY, SYS_CLK_PHASE, spi_clk_enable);
81	    ------------------------------------------------------------
82	
83	    ------------------------------------------------------------
84	    -- VUnit
85	    ------------------------------------------------------------
86	    test_runner_watchdog(runner, SIMULATION_TIMEOUT_TIME);
87	
88	    main: process
89	    begin
90	        test_runner_setup(runner, runner_cfg);
91	        info("Starting tb_spi_tx");
92	
93	        if ENABLE_DEBUG_PRINT then
94	            show(display_handler, debug);
95	        end if;
96	
97	        wait until simulation_done;
98	        info("Simulation done, all tests passed!" & LF);
99	
100	        test_runner_cleanup(runner);
101	        wait;
102	    end process;
103	    ------------------------------------------------------------
104	
105	    ------------------------------------------------------------
106	    -- Checker
107	    ------------------------------------------------------------
108	    checker: process
109	        variable random: RandomPType;
110	        variable expected_data: std_ulogic_vector(DATA_WIDTH - 1 downto 0);
111	
112	        procedure wait_spi_clk_cycles(cycles: natural) is begin
113	            for i in 0 to cycles - 1 loop
114	                wait until rising_edge(spi_clk);
115	            end loop;
116	            wait for PROPAGATION_TIME;
117	        end procedure;
118	
119	        procedure wait_tx_spi_clk_cycles(cycles: natural) is begin
120	            for i in 0 to cycles - 1 loop
121	                wait until tx_active_edge(spi_clk, SPI_CLK_POLARITY, SPI_CLK_PHASE);
122	            end loop;
123	            wait for PROPAGATION_TIME;
124	        end procedure;
125	
126	        procedure wait_chip_select_n_cycles(cycles: natural) is begin
127	            for i in 0 to cycles - 1 loop
128	                wait until active_edge_chip_select_n_assertion(spi_clk, SPI_CLK_POLARITY);
129	            end loop;
130	            wait for PROPAGATION_TIME;
131	        end procedure;
132	
133	        procedure test_reset_behavior is begin
134	            info("1.0) Testing reset behavior");
135	
136	            rst_n <= '1';
137	            tx_data_valid <= '0';
138	            tx_data <= (others => '0');
139	            wait_spi_clk_cycles(1);
140	
141	            rst_n <= '0';
142	            wait_spi_clk_cycles(1);
143	            check_equal(got => tx_is_ongoing, expected => '0', msg => "tx_is_ongoing - TX should be inactive during reset");
144	            check_equal(got => serial_data_out, expected => 'Z', msg => "serial_data_out - Serial data should be high-Z during reset");
145	            check_equal(got => spi_chip_select_n, expected => '1', msg => "spi_chip_select_n - Chip select should be inactive during reset");
146	
147	            rst_n <= '1';
148	            wait_spi_clk_cycles(1);
149	            check_equal(got => tx_is_ongoing, expected => '0', msg => "TX should remain inactive after reset");
150	
151	            info("Reset behavior test passed" & LF);
152	        end procedure;
153	
154	        procedure test_single_word_transmission is begin
155	            info("2.0) Testing single word transmission");
156	
157	            expected_data := random.RandSlv(Size => DATA_WIDTH);
158	
159	            tx_data <= expected_data;
160	            tx_data_valid <= '1';
161	            wait until tx_is_ongoing;
162	            check_equal(got => tx_is_ongoing, expected => '1', msg => "tx_is_ongoing - TX should be active");
163	            tx_data_valid <= '0';
164	            wait_spi_clk_cycles(1);
165	
166	            wait_chip_select_n_cycles(1);
167	            check_equal(got => spi_chip_select_n, expected => '0', msg => "spi_chip_select_n - Chip select should be active");
168	
169	            wait_tx_spi_clk_cycles(DATA_WIDTH);
170	
171	            wait_spi_clk_cycles(1);
172	            check_equal(got => tx_is_ongoing, expected => '0', msg => "TX should be inactive after transmission");
173	            check_equal(got => spi_chip_select_n, expected => '1', msg => "Chip select should be inactive after transmission");
174	
175	            info("Single word transmission test passed" & LF);
176	        end procedure;
177	
178	        procedure test_back_to_back_transmissions is begin
179	            info("3.0) Testing back-to-back transmissions");
180	
181	            expected_data := random.RandSlv(Size => DATA_WIDTH);
182	
183	            -- First transmission
184	            tx_data <= expected_data;
185	            tx_data_valid <= '1';
186	            wait_spi_clk_cycles(1);
187	            tx_data_valid <= '0';
188	
189	            -- Wait for almost complete
190	            wait_spi_clk_cycles(DATA_WIDTH - 2);
191	
192	            check_equal(got => tx_is_ongoing, expected => '1', msg => "TX should still be active before second transmission");
193	
194	            -- Second transmission before first completes
195	            expected_data := random.RandSlv(Size => DATA_WIDTH);
196	            tx_data <= expected_data;
197	            tx_data_valid <= '1';
198	            wait_spi_clk_cycles(1);
199	            tx_data_valid <= '0';
200	
201	            -- Wait for both transmissions
202	            wait_spi_clk_cycles(DATA_WIDTH);
203	
204	            wait_spi_clk_cycles(1);
205	            check_equal(got => tx_is_ongoing, expected => '0', msg => "TX should be inactive after all transmissions");
206	
207	            info("Back-to-back transmissions test passed" & LF);
208	        end procedure;
209	
210	        procedure test_back_to_back_with_chip_select_monitoring is
211	            variable first_data, second_data, third_data: std_ulogic_vector(DATA_WIDTH - 1 downto 0);
212	        begin
213	            info("4.0) Testing back-to-back transmissions with detailed chip select monitoring");
214	
215	            first_data := random.RandSlv(Size => DATA_WIDTH);
216	            second_data := random.RandSlv(Size => DATA_WIDTH);
217	            third_data := random.RandSlv(Size => DATA_WIDTH);
218	
219	            info("4.1) Overlapping transmission requests");
220	
221	            -- Start first transmission
222	            tx_data <= first_data;
223	            tx_data_valid <= '1';
224	            wait until tx_is_ongoing;
225	            check_equal(got => tx_is_ongoing, expected => '1', msg => "First TX should be active");
226	            wait until tx_data_ack;
227	            tx_data_valid <= '0';
228	
229	            -- Monitor chip select during first transmission
230	            wait_chip_select_n_cycles(1);
231	            check_equal(got => spi_chip_select_n, expected => '0', msg => "Chip select should be active during first transmission");
232	
233	            -- Wait partway through first transmission
234	            wait_tx_spi_clk_cycles(DATA_WIDTH / 2);
235	            check_equal(got => spi_chip_select_n, expected => '0', msg => "Chip select should remain active mid-transmission");
236	
237	            -- Start second transmission while first is still ongoing
238	            tx_data <= second_data;
239	            tx_data_valid <= '1';
240	            wait_spi_clk_cycles(1);
241	            check_equal(got => tx_is_ongoing, expected => '1', msg => "TX should still be active for first word");
242	            check_equal(got => spi_chip_select_n, expected => '0', msg => "Chip select should still be active for first word");
243	
244	            -- Wait for first transmission to complete
245	            wait_tx_spi_clk_cycles(DATA_WIDTH / 2);
246	
247	            -- Check if second transmission starts immediately
248	            wait until tx_data_ack;
249	            tx_data_valid <= '0';
250	
251	            -- Monitor chip select behavior during transition
252	            wait_spi_clk_cycles(2);
253	            check_equal(got => tx_is_ongoing, expected => '1', msg => "Second TX should be active");
254	            wait_chip_select_n_cycles(1);
255	            check_equal(got => spi_chip_select_n, expected => '0', msg => "Chip select should be active for second transmission");
256	
257	            -- Wait for second transmission to complete
258	            wait_tx_spi_clk_cycles(DATA_WIDTH);
259	
260	            info("4.2) Rapid successive transmissions");
261	
262	            -- Queue third transmission immediately after second
263	            tx_data <= third_data;
264	            tx_data_valid <= '1';
265	            wait until tx_data_ack;
266	            tx_data_valid <= '0';
267	
268	            -- Monitor continuous chip select behavior
269	            check_equal(got => tx_is_ongoing, expected => '1', msg => "Third TX should be active");
270	            wait_chip_select_n_cycles(1);
271	            check_equal(got => spi_chip_select_n, expected => '0', msg => "Chip select should be active for third transmission");
272	
273	            -- Wait for all transmissions to complete
274	            wait_tx_spi_clk_cycles(DATA_WIDTH);
275	            wait_spi_clk_cycles(2);
276	
277	            check_equal(got => tx_is_ongoing, expected => '0', msg => "All transmissions should be complete");
278	            check_equal(got => spi_chip_select_n, expected => '1', msg => "Chip select should be deasserted after all transmissions");
279	
280	            info("4.3) Testing immediate back-to-back with no gaps");
281	
282	            -- Rapid fire three transmissions
283	            for i in 0 to 2 loop
284	                expected_data := random.RandSlv(Size => DATA_WIDTH);
285	                tx_data <= expected_data;
286	                tx_data_valid <= '1';
287	
288	                if i = 0 then
289	                    wait until tx_is_ongoing;
290	                end if;
291	
292	                wait until tx_data_ack;
293	                tx_data_valid <= '0';
294	
295	                if i < 2 then
296	                    -- Verify transmission continues without gap
297	                    wait_spi_clk_cycles(1);
298	                    check_equal(got => tx_is_ongoing, expected => '1', msg => "TX should continue for transmission " & to_string(i + 1));
299	                end if;
300	            end loop;
301	
302	            -- Wait for final transmission to complete
303	            wait until not tx_is_ongoing;
304	            wait_spi_clk_cycles(2);
305	            check_equal(got => spi_chip_select_n, expected => '1', msg => "Chip select should be deasserted after rapid transmissions");
306	
307	            info("Back-to-back with chip select monitoring test passed" & LF);
308	        end procedure;
309	    begin
310	        random.InitSeed(tb_path & random'instance_name);
311	
312	        -- NOTE: Don't remove, else VUnit will not run the test suite
313	        wait_spi_clk_cycles(1);
314	
315	        while test_suite loop
316	            if run("test_reset_behavior") then
317	                test_reset_behavior;
318	            elsif run("test_single_word_transmission") then
319	                test_single_word_transmission;
320	            elsif run("test_back_to_back_transmissions") then
321	                test_back_to_back_transmissions;
322	            elsif run("test_back_to_back_with_chip_select_monitoring") then
323	                test_back_to_back_with_chip_select_monitoring;
324	            else
325	                assert false report "No test has been run!" severity failure;
326	            end if;
327	        end loop;
328	
329	        simulation_done <= true;
330	    end process;
331	    ------------------------------------------------------------
332	
333	    ------------------------------------------------------------
334	    -- DUT instantiation
335	    ------------------------------------------------------------
336	    DUT: entity work.spi_tx
337	        generic map (
338	            SPI_CLK_POLARITY => SPI_CLK_POLARITY,
339	            SPI_CLK_PHASE => SPI_CLK_PHASE,
340	            DATA_WIDTH => DATA_WIDTH,
341	            CONTROLLER_AND_NOT_PERIPHERAL => CONTROLLER_AND_NOT_PERIPHERAL,
342	            MSB_FIRST_AND_NOT_LSB => MSB_FIRST_AND_NOT_LSB,
343	            ENABLE_INTERNAL_CLOCK_GATING => true,
344	            USE_XILINX_CLK_GATE_AND_NOT_INTERNAL => false
345	        )
346	        port map (
347	            spi_clk_in => spi_clk,
348	            rst_n => rst_n,
349	            tx_data => tx_data,
350	            tx_data_valid => tx_data_valid,
351	            tx_data_ack => tx_data_ack,
352	            spi_clk_out => spi_clk_out,
353	            serial_data_out => serial_data_out,
354	            spi_chip_select_n => spi_chip_select_n,
355	            tx_is_ongoing => tx_is_ongoing
356	        );
357	    ------------------------------------------------------------
358	end architecture;
359

